		kuiYue: ["◇ **天魁在福德**：精神上常受年长男性启发", "◇ **天钺在官禄**：事业上女性上司或前辈为关键贵人", "◇ **天魁在田宅**：家族中男性长辈为家业支柱", "◇ **天钺在仆役**：朋友圈女性贵人多", "◇ **天魁在官禄**：事业上男性上司或前辈为关键贵人", "◇ **天钺在迁移**：外出逢女性贵人，异地女师相助", "◇ **天魁在财帛**：财运来自男性长辈或前辈型贵人", "◇ **天钺在夫妻**：配偶为女性贵人型（或其家中女性长辈）", "◇ **天魁在子女**：儿子贵气或男性晚辈助力", "◇ **天钺在兄弟**：姐妹或女性兄弟辈有贵气", "◇ **天魁在夫妻**：配偶为男性贵人型（或其家中男性长辈）", "◇ **天钺在命宫**：终身贵人常伴，关键时刻夜间有女性长辈或女师相助", "◇ **天魁在命宫**：终身贵人常伴，关键时刻白日有男性长辈或男师相助", "◇ **天魁在父母**：父亲或男性长辈为第一贵人", "◇ **天钺在疾厄**：遇病有良医（偏女医师或护理）", "◇ **天钺在财帛**：财运来自女性长辈或女性合伙人", "◇ **天魁在迁移**：外出逢男性贵人，异地男师提携", "◇ **天魁在疾厄**：遇病有良医（偏男医师）", "◇ **天钺在父母**：母亲或女性长辈为第一贵人", "◇ **天钺在福德**：精神上常受年长女性启发", "◇ **天魁在仆役**：朋友圈男性贵人多", "◇ **天钺在田宅**：家族中女性长辈为家业支柱", "◇ **天魁在兄弟**：兄弟中有男性贵人", "◇ **天钺在子女**：女儿贵气或女性晚辈助力"],
