				"✦ 左辅：外出多遇贵人相助。",
				"**太阳化忌（落陷）** 在迁移：",
				"✦ 文昌：外出文书顺利，异地考运佳，适合文教迁移。",
				"**天机化禄（庙旺）** 在迁移：",
				"▶ 化禄：化禄，以智慧与变通生财，知识型或策划型收入最顺遂，财来自脑力与人脉。",
				"✦ 天魁：异地男性贵人多。",
				"**天机化忌（庙旺）** 在迁移：",
				"▶ 化忌：化忌，多变焦虑加剧，感情多波折，神经系统承压，需特别注意稳定心性。",
				"**太阳化权（落陷）** 在迁移：",
				"▶ 化权：化权，在公众事务或政务领域掌权，社会地位与话语权显著提升，是非常有力的事业格局。",
				"**天同化忌** 在迁移：",
				"▶ 化忌：化忌，福德受损，感情多波折，生活中不顺心事增多，宜主动调整心态积极面对。",
				"**太阳化权（庙旺）** 在迁移：",
				"**天机化科（庙旺）** 在迁移：",
				"▶ 化科：化科，因才艺或学识获得名声，文教或技术领域成就显著，贵人提携较多。",
				"**天同化禄** 在迁移：",
				"▶ 化禄：化禄，福禄双美，生活顺遂安乐，是天同最理想的状态，衣食无忧，幸福感强。",
				"**天同化权** 在迁移：",
				"▶ 化权：化权，在服务业或相关领域可担任领导，较少见但有效，为人更有主见与决断力。",
				"**天机化权（庙旺）** 在迁移：",
